-- What the website publishes: every live happy hour at an open establishment, one row per window.
-- Used by the deploy job: psql "$SUPABASE_DB_URL" -v ON_ERROR_STOP=1 -f tools/site_export.sql  (writes db.csv)
\copy (select e.id as _key, e.name, e.neighborhood, e.address, e.phone, e.website, e.instagram, e.lat, e.lng, e.type, e.about, case when e.featured then 'yes' else '' end as featured, case when e.classic then 'yes' else '' end as classic, array_to_string(h.days, ',') as days, to_char(h.start_time, 'HH24:MI') as start, to_char(h.end_time, 'HH24:MI') as "end", array_to_string(h.deals, '|') as deals, array_to_string(h.tags, ',') as tags, to_char(h.verified_on, 'YYYY-MM-DD') as verified, h.source_url from happy_hours h join establishments e on e.id = h.establishment_id where h.review_status = 'live' and e.status not in ('closed', 'private', 'inactive') order by e.name, h.start_time) to 'db.csv' with (format csv, header)
select 'Exported ' || count(*) || ' happy hour windows at ' || count(distinct h.establishment_id) || ' establishments' from happy_hours h join establishments e on e.id = h.establishment_id where h.review_status = 'live' and e.status not in ('closed', 'private', 'inactive');
-- Weekly specials at the same places (daily.csv)
\copy (select e.name, e.neighborhood, e.address, array_to_string(d.days, ',') as days, to_char(d.start_time, 'HH24:MI') as start, to_char(d.end_time, 'HH24:MI') as "end", d.special, to_char(d.verified_on, 'YYYY-MM-DD') as verified, d.source_url from daily_specials d join establishments e on e.id = d.establishment_id where d.review_status = 'live' and e.status not in ('closed', 'private', 'inactive') order by e.name) to 'daily.csv' with (format csv, header)
